import React from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, LineElement, PointElement, LinearScale, CategoryScale, Filler, Tooltip } from 'chart.js';
ChartJS.register(LineElement, PointElement, LinearScale, CategoryScale, Filler, Tooltip);

const labels = ['00:00','04:00','08:00','12:00','16:00','20:00','24:00'];
const rand = () => Array.from({ length: 7 }, () => +(Math.random() * .7 + .15).toFixed(2));
const colors = { Fire:'#fb923c', Smoke:'#94a3b8', Gun:'#f87171', Knife:'#facc15', Falling:'#a78bfa', Violence:'#f43f5e' };

const confData = {
  labels,
  datasets: Object.entries(colors).map(([k, c]) => ({
    label: k, data: rand(), borderColor: c,
    borderWidth: 1.5, pointRadius: 2, fill: false, tension: .4
  }))
};

const detHours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0') + ':00');
const detData = {
  labels: detHours,
  datasets: [{
    data: [12,8,20,15,30,45,28,35,22,18,40,32,15,10,25,38,42,20,14,8,30,18,12,5],
    borderColor: '#3b82f6', borderWidth: 2,
    fill: true, backgroundColor: 'rgba(59,130,246,.1)',
    pointRadius: 0, tension: .4
  }]
};

const opts = (yMax) => ({
  plugins: { legend: { display: false } },
  animation: false,
  scales: {
    x: { ticks: { color: '#64748b', font: { size: 9 } }, grid: { color: '#1e2d47' } },
    y: { max: yMax, ticks: { color: '#64748b', font: { size: 9 } }, grid: { color: '#1e2d47' } }
  }
});

export default function ChartsRow() {
  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 10 }}>
      {/* Confidence Chart */}
      <div style={{ background: '#151d2e', border: '1px solid #1e2d47', borderRadius: 8, padding: 10 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>Confidence Score Graph</span>
          <select style={{ background: '#1a2340', border: '1px solid #253550', color: '#94a3b8', fontSize: 10, padding: '2px 5px', borderRadius: 4 }}>
            <option>All Classes</option>
          </select>
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 6 }}>
          {Object.entries(colors).map(([k, c]) => (
            <span key={k} style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9, color: '#64748b' }}>
              <span style={{ width: 6, height: 6, borderRadius: '50%', background: c, display: 'inline-block' }}></span>{k}
            </span>
          ))}
        </div>
        <Line data={confData} options={opts(1)} />
      </div>

      {/* Detections Over Time */}
      <div style={{ background: '#151d2e', border: '1px solid #1e2d47', borderRadius: 8, padding: 10 }}>
        <div style={{ marginBottom: 8 }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>Detections Over Time</span>
        </div>
        <Line data={detData} options={opts(50)} />
      </div>
    </div>
  );
}
